  "substitution_bias": [
    {
      "id": 16051,
      "difficulty": "bridge",
      "conceptCluster": "prices_inflation",
      "primarySkill": "substitution_bias",
      "secondarySkills": [],
      "repairSkill": "substitution_bias",
      "commonError": "Compares total bills instead of their increases, or ignores the stipulated substitute basket.",
      "q": "A household initially buys two apples and two pears at $1 each, costing $4. Apples then cost $3 and pears still $1. The old basket now costs $8, but four pears cost $4 and are stipulated to give this household the same satisfaction. How much does the fixed-basket cost increase overstate the increase needed for that satisfaction?",
      "options": [
        "Understates by $4: fixed-basket cost is unchanged; the equally satisfactory basket’s cost rises $4",
        "Overstates by $4: fixed-basket cost rises $4; the equally satisfactory basket’s cost is unchanged",
        "Overstates by $8: the fixed basket’s entire $8 bill is an increase; substitute cost is unchanged",
        "No overstatement: the fixed and equally satisfactory baskets each cost $4 more than before"
      ],
      "tag": "cpi_bias",
      "type": "application",
      "objective": "LO25.2",
      "feedback": "The fixed basket’s increase is 8−4=4. The equally satisfactory adjusted basket’s increase is 4−4=0. The fixed basket therefore overstates the needed increase by $4. The supplied satisfaction assumption makes this a cost comparison rather than a claim that arbitrary bundles are equivalent.",
      "aHash": "0f7a23702e8c4b38f46d9f3ed335f2f7a54c0e07a2f5ad861bb2aa0f5954d2c8",
      "canonicalId": "ECON-NL-SUBSTITUTION-BIAS-6011",
      "primaryConceptId": "cpi-bias",
      "secondaryConceptIds": [
        "cpi-and-inflation-measurement"
      ],
      "instructionalRole": "bridge",
      "canonicalDifficulty": "hard",
      "originalSourcePool": "substitution_bias",
      "originalBossTier": null,
      "composerLibrarySha256": "ca58924188abfe6a274244df230dca1128f6af5207512de9f9dd0efc09ece457"
    }
  ],
